/** Actual all7earned proofs, live loaded native machines and final OP2workshop assessment. */
final class CreateWorkshopRuntime {
 static final BlockPos CENTER=new BlockPos(544,87,512),BARREL=CENTER.west(2),LAMP=CENTER.west(3);
 static void run(GameTestHelper h,Runnable done)throws Exception{
  var level=h.getLevel();var server=level.getServer();var id=ConstructionService.store(server).projects().stream().filter(q->q.blueprint().equals(BlueprintRegistry.HUT)).findFirst().orElseThrow().owner();var actor=server.getPlayerList().getPlayer(id);if(actor==null)actor=ClaimRuntimeTests.vanillaPlayer(level,id,"HallOwner");final var p=actor;server.getPlayerList().deop(p.getGameProfile());var store=CommerceService.store(server);var track=store.professions(id).track(Profession.ENGINEER);h.assertTrue(track.completedQuestIds().contains(CreateTransmissionInspection.QUEST),"Use actual native seven earned Apprentice proofs before assessment");
  // Explicit copied-QA permission fixture; sparse production inspection itself never loads chunks.
  for(int x=31;x<=36;x++)for(int z=31;z<=32;z++){level.getChunk(x,z);var at=new BlockPos(x*16,87,z*16);ClaimRuntimeTests.ftbUnclaim(level,at);ClaimRuntimeTests.ftbClaim(p,at);ClaimRuntimeTests.opacUnclaim(level,at);ClaimRuntimeTests.opacClaim(level,id,at);}BlacksmithRepairRuntime.near(p,CENTER);
  if(track.completedQuestIds().contains(CreateWorkshopInspection.QUEST)){server.tickRateManager().setTickRate(20);h.runAfterDelay(80,()->{try{h.assertTrue(CreateWorkshopInspection.validate(p,CENTER).startsWith("workshop=")&&track.xp()==800&&track.completedQuestIds().size()==8&&store.professions(id).rank(Profession.ENGINEER,ProfessionService.quests())==ProfessionRank.JOURNEYMAN,"Second JVM restores all8actually earned800XP/Journeyman and working native workshop");CommerceService.verifyReceipt(p);var project=ConstructionService.store(server).projects().stream().filter(q->q.blueprint().toString().equals(Profession.ENGINEER.buildingId())).findFirst().orElseThrow();h.assertTrue(ConstructionService.structureIntact(level,project),"Original paid Engineer premises and Ivo identity remain intact");com.mojang.logging.LogUtils.getLogger().info("CREATE_WORKSHOP_RESTART_PASSED: all8native Apprentice proofs/800XP/Journeyman/live workshop/control/storage/lighting/original Workshop-Ivo/canonical audit and receipt persist after actual server restart, no replay");done.run();}catch(Exception failure){h.fail(failure.toString());}});return;}
  h.assertTrue(track.xp()==700&&track.completedQuestIds().size()==7,"Final native workshop starts only from genuine all7/700XP, no artificial rank");
  for(var at:List.of(BARREL,LAMP))h.assertTrue(level.getBlockState(at).isAir()||!level.getBlockState(at).getFluidState().isEmpty(),"Native furnishings only use private clear/replaceable cells");CreateDriveRuntime.place(h,p,BARREL,new ItemStack(Items.BARREL),BARREL.below(),Direction.UP);CreateDriveRuntime.place(h,p,LAMP,new ItemStack(Items.LANTERN),LAMP.below(),Direction.UP);
  h.runAfterDelay(160,()->{try{
   h.assertTrue(CreateWorkshopInspection.validate(p,CENTER).startsWith("workshop="),"Actual maintained waterwheel/transmission/press/millstone and controlled shutoff have permitted maintenance access/storage/light");var adminId=ConstructionService.store(server).projects().stream().filter(q->ProfessionPremises.contains(q.blueprint())).findFirst().orElseThrow().owner();var admin=server.getPlayerList().getPlayer(adminId);h.assertTrue(admin!=null&&!adminId.equals(id),"Real independent operator attends final workshop");server.getPlayerList().op(admin.getGameProfile());admin.moveTo(CENTER.getX()+1.5,CENTER.getY(),CENTER.getZ()-2.5);p.moveTo(CENTER.getX()+.5,CENTER.getY(),CENTER.getZ()-2.5);try{
    var review=ProfessionInspectionService.review(admin,p,CreateWorkshopInspection.QUEST,CENTER,"Inspected personal production power controls safe maintenance lighting storage and owner consent");var remote=CreateTransmissionRuntime.SMALL.south().above();CreateTransmissionRuntime.toggle(h,p,remote,true);boolean denied=false;try{ProfessionInspectionService.confirm(admin,review);}catch(IllegalStateException expected){denied=true;}h.assertTrue(denied&&store.professions(id).track(Profession.ENGINEER).xp()==700,"Actual changed control geometry near a remote machine outside the central8block room invalidates the sparse workshop snapshot");CreateTransmissionRuntime.toggle(h,p,remote,false);admin.moveTo(CENTER.getX()+1.5,CENTER.getY(),CENTER.getZ()-2.5);p.moveTo(CENTER.getX()+.5,CENTER.getY(),CENTER.getZ()-2.5);
    review=ProfessionInspectionService.review(admin,p,CreateWorkshopInspection.QUEST,CENTER,"Inspected personal production power controls safe maintenance lighting storage and owner consent");ProfessionInspectionService.confirm(admin,review);var earned=store.professions(id);h.assertTrue(earned.track(Profession.ENGINEER).xp()==800&&earned.track(Profession.ENGINEER).completedQuestIds().size()==8&&earned.rank(Profession.ENGINEER,ProfessionService.quests())==ProfessionRank.JOURNEYMAN,"All8real Engineer Apprentice proofs earn800XP/Journeyman and purchase rights, no Master title or free equipment");CommerceService.verifyReceipt(p);h.assertTrue(EconomyStore.open(server.getWorldPath(net.minecraft.world.level.storage.LevelResource.ROOT).resolve("data")).professions(id).equals(earned),"Final actual profession assessment and canonical receipt reopen exactly");com.mojang.logging.LogUtils.getLogger().info("CREATE_WORKSHOP_NATIVE_PASSED: all7real prerequisites, actual native barrel/lighting placement, real loaded permitted power/gears/press/millstone/clutch-stop/maintenance access, remote changed-geometry refusal and OP2final assessment, all8earned800XP/Journeyman/original Workshop-Ivo; private raw furnishing/time fixtures only");done.run();
   }finally{server.getPlayerList().deop(admin.getGameProfile());}
  }catch(Exception failure){h.fail("Native final workshop: "+failure);}});
 }
}
